mapper.select:
SELECT /*LGVCOM00100.retrieveUserPopupList*/ em.employee_number AS employee_no ,em.full_name_local AS employee_name ,lcc.common_code_desc AS employee_grade ,em.organization_id AS organization_id ,em.org_name_local AS organization_name ,lgvhr_common_pkg.get_shift_type_code_func(#{LGVHR_PROJECT_SESSION.subsidiaryCode} ,em.employee_number ,TRUNC( to_date(#{attDate}, 'DD/MM/YYYY') )) AS shift_type ,lum.application_user_id AS application_user_id ,lum.department_code AS organization_code FROM emp_master em ,lgcom_common_code_c lcc ,lgcom_user_m lum WHERE lcc.common_code = em.grade_title AND em.employee_number = lum.user_name AND lcc.code_type_code = 'IF_VIETNAM_GRADE_TITLE'
AND em.employee_number like '%' || UPPER(#{employeeNo}) || '%'
AND UPPER(em.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
AND em.organization_id = #{orgId}
AND em.assignment_category = #{assignmentCategory}
AND em.organization_id IN ( SELECT tacn.organization_id FROM tb_att_contract_n tacn WHERE tacn.time_attend_contact_user_id = #{LGVHR_PROJECT_SESSION.employeeNo} )
AND em.organization_id IN ( SELECT DISTINCT t.organization_id FROM emp_master t WHERE assignment_category = 'LGD_OW' START WITH subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} /* 변수: 세션 법인코드 */ AND employee_number = #{LGVHR_PROJECT_SESSION.employeeNo} /* 변수: 세션 로긴자 사번 */ CONNECT BY NOCYCLE PRIOR employee_number = supervisor )
AND em.fse_yn = #{fseYn}
AND em.flsa_yn = #{flsaYn}
ORDER BY em.employee_number
